/**
 * The podcast's RSS feed to the shape of src/data/podcast.json. Pure: no
 * network, no file system. Used by `npm run podcast:sync` and by the panel's
 * "Yeni bölümleri çek" (functions/api/cms/podcast/pull.ts).
 *
 * Deliberately not clever: no XML library, because the shape being read is
 * a few fields per item from a feed generated by one host, and a dependency
 * for that is a dependency to keep updated. The feed is third-party text:
 * everything it gives becomes plain text, and nothing here throws anything
 * but FeedError.
 */

export const FEED = 'https://anchor.fm/s/fe335014/podcast/rss';

/** Where else the show is listed. These are subscribe links, not players. */
export const PLATFORMS = {
  spotify: 'https://open.spotify.com/show/7rA9IoDcI5ybW0Y4HQlmHq',
  apple: 'https://podcasts.apple.com/podcast/id1797656975',
  castbox: 'https://castbox.fm/channel/6480428',
  rss: FEED,
};

export interface PodcastEpisode {
  guid: string;
  title: string;
  /** ISO 8601, so each language can format it its own way. */
  pubDate: string;
  durationSeconds: number;
  audioUrl: string;
  audioBytes: number;
  image: string;
  description: string;
}

export interface PodcastData {
  syncedAt: string;
  title: string;
  description: string;
  image: string;
  platforms: typeof PLATFORMS;
  episodes: PodcastEpisode[];
}

/** Why a feed could not be used. The message is ours, never the feed's text. */
export class FeedError extends Error {}

const cdata = (s: string): string => s.replace(/^\s*<!\[CDATA\[/, '').replace(/\]\]>\s*$/, '').trim();

function tag(source: string, name: string): string {
  const m = new RegExp(`<${name}(?:\\s[^>]*)?>([\\s\\S]*?)</${name}>`).exec(source);
  return m ? cdata(m[1]) : '';
}

function attr(source: string, element: string, name: string): string {
  const m = new RegExp(`<${element}[^>]*\\s${name}="([^"]*)"`).exec(source);
  return m ? decodeEntities(m[1]) : '';
}

function decodeEntities(s: string): string {
  return s
    .replace(/&nbsp;/g, ' ')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;|&apos;/g, "'")
    .replace(/&amp;/g, '&');
}

/**
 * The house rules of tests/no-em-dashes.test.ts, applied to what the feed
 * says: no em dash, and no spaced `--`, which that test also reads as a
 * dash on the built page. Both become a spaced hyphen. Without this, an
 * episode whose description has an em dash could never be submitted in the
 * panel (submit refuses it) and would fail CI if synced by hand.
 */
export function houseText(s: string): string {
  return s.replace(/\s*—\s*/g, ' - ').replace(/(\w)\s+--\s+(?=\w)/g, '$1 - ');
}

/** Entities, then tags, then collapse. Feed descriptions are HTML. */
export function plainText(html: string): string {
  const text = html
    .replace(/<br\s*\/?>/gi, ' ')
    .replace(/<\/p>/gi, ' ')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;|&apos;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
  return houseText(text);
}

/** `itunes:duration` is HH:MM:SS, MM:SS, or already seconds. */
export function durationSeconds(raw: string): number {
  if (!raw) return 0;
  if (/^\d+$/.test(raw)) return Number(raw);
  const parts = raw.split(':').map(Number);
  if (parts.some(Number.isNaN)) return 0;
  return parts.reduce((total, p) => total * 60 + p, 0);
}

function isoDate(raw: string): string {
  const at = new Date(raw);
  if (!raw || Number.isNaN(at.getTime())) throw new FeedError('An episode has no readable date');
  return at.toISOString();
}

/**
 * The feed's XML as podcast.json's data, episodes newest first. Throws
 * FeedError for a feed with no episodes, or an episode without audio, a
 * title or a date.
 */
export function parseFeed(xml: string, syncedAt: string): PodcastData {
  const first = xml.indexOf('<item>');
  const channel = first === -1 ? xml : xml.slice(0, first);
  const items = [...xml.matchAll(/<item>([\s\S]*?)<\/item>/g)].map((m) => m[1]);
  if (items.length === 0) throw new FeedError('The feed has no episodes');

  const episodes: PodcastEpisode[] = items.map((item) => {
    const audioUrl = attr(item, 'enclosure', 'url');
    const title = houseText(decodeEntities(tag(item, 'title')));
    if (!audioUrl || !title) throw new FeedError('An episode has no audio or no title');
    return {
      guid: tag(item, 'guid') || audioUrl,
      title,
      pubDate: isoDate(tag(item, 'pubDate')),
      durationSeconds: durationSeconds(tag(item, 'itunes:duration')),
      audioUrl,
      audioBytes: Number(attr(item, 'enclosure', 'length')) || 0,
      image: attr(item, 'itunes:image', 'href'),
      description: plainText(tag(item, 'description')),
    };
  });
  // Newest first, which the page and tests/podcast.test.ts assume.
  episodes.sort((a, b) => Date.parse(b.pubDate) - Date.parse(a.pubDate));

  return {
    // Recorded so a reader of the file knows how stale it might be.
    syncedAt,
    title: houseText(decodeEntities(tag(channel, 'title'))),
    description: plainText(tag(channel, 'description')),
    image: attr(channel, 'itunes:image', 'href'),
    platforms: { ...PLATFORMS },
    episodes,
  };
}
